title: Cache Repeated Function Calls
impact: MEDIUM
impactDescription: avoid redundant computation
tags: javascript, cache, memoization, performance
---

## Cache Repeated Function Calls

Use a module-level Map to cache function results when the same function is called repeatedly with the same inputs during render.

**Incorrect (redundant computation):**

```typescript
function ProjectList({ projects }: { projects: Project[] }) {
  return (
    <div>
      {projects.map(project => {
        // slugify() called 100+ times for same project names
        const slug = slugify(project.name)

        return <ProjectCard key={project.id} slug={slug} />
      })}
    </div>
  )
}
```

**Correct (cached results):**

```typescript
// Module-level cache
const slugifyCache = new Map<string, string>()

function cachedSlugify(text: string): string {
  if (slugifyCache.has(text)) {
    return slugifyCache.get(text)!
  }
  const result = slugify(text)
  slugifyCache.set(text, result)
  return result
}

function ProjectList({ projects }: { projects: Project[] }) {
  return (
    <div>
      {projects.map(project => {
        // Computed only once per unique project name
        const slug = cachedSlugify(project.name)

        return <ProjectCard key={project.id} slug={slug} />
      })}
    </div>
  )
}
```

**Simpler pattern for single-value functions:**

```typescript
let isLoggedInCache: boolean | null = null

function isLoggedIn(): boolean {
  if (isLoggedInCache !== null) {
    return isLoggedInCache
  }

  isLoggedInCache = document.cookie.includes('auth=')
  return isLoggedInCache
}

// Clear cache when auth changes
function onAuthChange() {
  isLoggedInCache = null
}
```

Use a Map (not a hook) so it works everywhere: utilities, event handlers, not just React components.

Reference: [How we made the Vercel Dashboard twice as fast](https://vercel.com/blog/how-we-made-the-vercel-dashboard-twice-as-fast)

import { NextApiRequest, NextApiResponse } from "next";

import prisma from "@/lib/prisma";

export default async function handle(
  req: NextApiRequest,
  res: NextApiResponse,
) {
  // We only allow POST requests
  if (req.method !== "POST") {
    res.status(405).json({ message: "Method Not Allowed" });
    return;
  }

  // POST /api/record_reaction

  const { viewId, pageNumber, type } = req.body as {
    viewId: string;
    pageNumber: number;
    type: string;
  };

  try {
    const reaction = await prisma.reaction.create({
      data: {
        viewId,
        pageNumber,
        type,
      },
      include: {
        view: {
          select: {
            documentId: true,
            dataroomId: true,
            linkId: true,
            viewerEmail: true,
            viewerId: true,
            teamId: true,
          },
        },
      },
    });

    if (!reaction) {
      res.status(500).json({ message: "Internal Server Error" });
      return;
    }



    res.status(200).json({ message: "Reaction recorded" });
    return;
  } catch (error) {
    res.status(500).json({ message: "Internal Server Error" });
    return;
  }
}

import { NextApiResponse } from "next";
import { NextResponse } from "next/server";

import prisma from "@/lib/prisma";

import {
  assertDocumentAccess,
  assertLinkAccess,
  canAccessDataroom,
} from "./entitlements";
import { isDataroomScopedRole } from "./permissions";

/**
 * App-router variant of the team-level scope check. Billing routes are
 * team-level actions, so a dataroom-scoped member is denied outright. Returns a
 * 403 `NextResponse` when denied, or `null` when access is allowed.
 */
export async function denyDataroomScopedMember({
  userId,
  teamId,
  role,
}: {
  userId: string;
  teamId: string;
  role?: string;
}): Promise<NextResponse | null> {
  let resolvedRole = role;
  if (resolvedRole === undefined) {
    const membership = await prisma.userTeam.findUnique({
      where: { userId_teamId: { userId, teamId } },
      select: { role: true },
    });
    resolvedRole = membership?.role;
  }

  if (!resolvedRole || !isDataroomScopedRole(resolvedRole)) {
    return null;
  }

  return NextResponse.json(
    { error: "You do not have permission to perform this action." },
    { status: 403 },
  );
}

/**
 * Lightweight inline guard for team routes that have NOT yet been migrated to
 * the `withTeam` session wrapper. It enforces two invariants for the
 * dataroom-scoped role on top of a route's existing membership check:
 *
 *  1. If `dataroomId` is provided, a scoped member must be assigned to that
 *     room (closes cross-room IDOR for assigned-vs-unassigned rooms).
 *  2. If `dataroomId` is NOT provided (a team-level route), a scoped member is
 *     denied outright (default-deny — these routes are not part of the scoped
 *     surface).
 *
 * Returns `true` if the request was denied (and a response was sent); the
 * caller should `return` immediately. Returns `false` when access is allowed.
 *
 * Non-scoped roles (ADMIN/MANAGER/MEMBER) are never affected by this guard.
 */
export async function enforceDataroomMemberScope({
  userId,
  teamId,
  dataroomId,
  res,
  role,
}: {
  userId: string;
  teamId: string;
  dataroomId?: string | null;
  res: NextApiResponse;
  /** Optional pre-loaded role to avoid an extra query. */
  role?: string;
}): Promise<boolean> {
  let resolvedRole = role;
  if (resolvedRole === undefined) {
    const membership = await prisma.userTeam.findUnique({
      where: { userId_teamId: { userId, teamId } },
      select: { role: true },
    });
    resolvedRole = membership?.role;
  }

  if (!resolvedRole || !isDataroomScopedRole(resolvedRole)) {
    return false;
  }

  if (!dataroomId) {
    res
      .status(403)
      .json({ error: "You do not have permission to perform this action." });
    return true;
  }

  const allowed = await prisma.userDataroom.findUnique({
    where: { userId_dataroomId: { userId, dataroomId } },
    select: { dataroomId: true },
  });

  if (!canAccessDataroom(resolvedRole, allowed ? [dataroomId] : [], dataroomId)) {
    res
      .status(403)
      .json({ error: "You do not have access to this data room." });
    return true;
  }

  return false;
}

/**
 * Inline link guard. Denies a scoped member that tries to act on a link which
 * resolves to a dataroom/document outside their assigned rooms. Returns `true`
 * (and sends a 403) when denied. Non-scoped roles always pass.
 */
export async function enforceLinkMemberScope({
  userId,
  teamId,
  linkId,
  res,
  role,
}: {
  userId: string;
  teamId: string;
  linkId: string;
  res: NextApiResponse;
  role?: string;
}): Promise<boolean> {
  let resolvedRole = role;
  if (resolvedRole === undefined) {
    const membership = await prisma.userTeam.findUnique({
      where: { userId_teamId: { userId, teamId } },
      select: { role: true },
    });
    resolvedRole = membership?.role;
  }

  if (!resolvedRole || !isDataroomScopedRole(resolvedRole)) {
    return false;
  }

  const allowed = await assertLinkAccess({
    role: resolvedRole,
    userId,
    teamId,
    linkId,
  });

  if (!allowed) {
    res.status(403).json({ error: "You do not have access to this link." });
    return true;
  }

  return false;
}

/**
 * Inline document guard. Denies a scoped member that tries to act on a document
 * which does not live in any of their assigned rooms. Returns `true` (and sends
 * a 403) when denied. Non-scoped roles always pass.
 */
export async function enforceDocumentMemberScope({
  userId,
  teamId,
  documentId,
  res,
  role,
}: {
  userId: string;
  teamId: string;
  documentId: string;
  res: NextApiResponse;
  role?: string;
}): Promise<boolean> {
  let resolvedRole = role;
  if (resolvedRole === undefined) {
    const membership = await prisma.userTeam.findUnique({
      where: { userId_teamId: { userId, teamId } },
      select: { role: true },
    });
    resolvedRole = membership?.role;
  }

  if (!resolvedRole || !isDataroomScopedRole(resolvedRole)) {
    return false;
  }

  const allowed = await assertDocumentAccess({
    role: resolvedRole,
    userId,
    teamId,
    documentId,
  });

  if (!allowed) {
    res.status(403).json({ error: "You do not have access to this document." });
    return true;
  }

  return false;
}

import { Role } from "@prisma/client";

import prisma from "@/lib/prisma";

import { isDataroomScopedRole } from "./permissions";

/**
 * Dataroom-entitlement helpers ("which rooms"), complementing
 * {@link getPermissionsByRole} ("what verbs"). Only DATAROOM_MEMBER is scoped.
 */

/** Returns the dataroom ids a user is explicitly assigned to within a team. */
export async function getAllowedDataroomIds(
  userId: string,
  teamId: string,
): Promise<string[]> {
  const rows = await prisma.userDataroom.findMany({
    where: { userId, teamId },
    select: { dataroomId: true },
  });
  return rows.map((r) => r.dataroomId);
}

/** Whether `role` may access `dataroomId`. Scoped roles need it in `allowedIds`. */
export function canAccessDataroom(
  role: Role | string,
  allowedIds: string[],
  dataroomId: string,
): boolean {
  if (!isDataroomScopedRole(role)) return true;
  return allowedIds.includes(dataroomId);
}

/**
 * Whether `role` may perform room-manager actions on `dataroomId`: upload
 * (documents.write), links (links.read/write), and folders (datarooms.write).
 * NOTE: destructive ops (delete/freeze) stay ADMIN/MANAGER-only via `requiredRoles`.
 */
export function canManageDataroom(
  role: Role | string,
  allowedIds: string[],
  dataroomId: string,
): boolean {
  return canAccessDataroom(role, allowedIds, dataroomId);
}

/** Scoped roles may access a document only if it lives in an assigned dataroom. */
export async function assertDocumentAccess({
  role,
  userId,
  teamId,
  documentId,
  allowedIds,
}: {
  role: Role | string;
  userId: string;
  teamId: string;
  documentId: string;
  allowedIds?: string[];
}): Promise<boolean> {
  if (!isDataroomScopedRole(role)) return true;

  const ids = allowedIds ?? (await getAllowedDataroomIds(userId, teamId));
  if (ids.length === 0) return false;

  const match = await prisma.dataroomDocument.findFirst({
    where: {
      documentId,
      dataroomId: { in: ids },
    },
    select: { id: true },
  });
  return !!match;
}

/** Scoped roles may access a link only if it resolves to an assigned dataroom. */
export async function assertLinkAccess({
  role,
  userId,
  teamId,
  linkId,
  allowedIds,
}: {
  role: Role | string;
  userId: string;
  teamId: string;
  linkId: string;
  allowedIds?: string[];
}): Promise<boolean> {
  if (!isDataroomScopedRole(role)) return true;

  const ids = allowedIds ?? (await getAllowedDataroomIds(userId, teamId));
  if (ids.length === 0) return false;

  const link = await prisma.link.findUnique({
    where: { id: linkId },
    select: { dataroomId: true, documentId: true, teamId: true },
  });
  if (!link || link.teamId !== teamId) return false;

  if (link.dataroomId) {
    return ids.includes(link.dataroomId);
  }
  if (link.documentId) {
    return assertDocumentAccess({
      role,
      userId,
      teamId,
      documentId: link.documentId,
      allowedIds: ids,
    });
  }
  // Links with neither dataroom nor document are denied for scoped roles.
  return false;
}

import { Role } from "@prisma/client";

/**
 * Granular permission verbs used by the session `withTeam` wrapper. A role maps
 * to a set of these via {@link getPermissionsByRole}; routes declare the verb(s)
 * they require. This is the "what verbs" layer (the "which rooms" layer is the
 * UserDataroom entitlement check, which a role alone cannot encode).
 */
export type PermissionAction =
  | "datarooms.read"
  | "datarooms.write"
  // Read access to the team-wide "All Documents" list/search.
  | "documents.read"
  // Create/upload documents and attach them to datarooms.
  | "documents.write"
  | "links.read"
  | "links.write"
  // Read analytics scoped to an individual dataroom/document.
  | "analytics.read"
  // Read team-wide analytics (the global dashboard).
  | "analytics.team"
  | "team.read"
  | "team.write"
  // Manage members (invite/remove/change role).
  | "members.write"
  | "tokens.write"
  | "webhooks.write"
  | "domains.write"
  | "branding.write"
  // SAML / SSO configuration (admin only).
  | "sso.write";

const ALL_PERMISSIONS: PermissionAction[] = [
  "datarooms.read",
  "datarooms.write",
  "documents.read",
  "documents.write",
  "links.read",
  "links.write",
  "analytics.read",
  "analytics.team",
  "team.read",
  "team.write",
  "members.write",
  "tokens.write",
  "webhooks.write",
  "domains.write",
  "branding.write",
  "sso.write",
];

// MANAGER gets everything except the admin-only structural operations.
const MANAGER_DENIED: PermissionAction[] = ["members.write", "sso.write"];

// MEMBER keeps today's broad behaviour: team read/write minus the
// admin/manager-only structural operations.
const MEMBER_DENIED: PermissionAction[] = [
  "members.write",
  "tokens.write",
  "webhooks.write",
  "domains.write",
  "sso.write",
];

// The minimal verb set a DATAROOM_MEMBER holds. Notably this excludes
// `documents.read` (the team-wide All Documents list), `analytics.team`, and
// every `team.*`/`members.write` verb. The per-room entitlement check (see
// `lib/api/rbac/entitlements.ts`) further restricts which datarooms these
// verbs apply to.
const DATAROOM_MEMBER_PERMISSIONS: PermissionAction[] = [
  "datarooms.read",
  "datarooms.write",
  "documents.write",
  "links.read",
  "links.write",
  "analytics.read",
];

/**
 * Returns the set of permission verbs granted to a role. The set is the single
 * source of truth for "what verbs" a role can perform, mirroring Dub's
 * `getPermissionsByRole`.
 */
export function getPermissionsByRole(
  role: Role | string,
): Set<PermissionAction> {
  switch (role) {
    case "ADMIN":
      return new Set(ALL_PERMISSIONS);
    case "MANAGER":
      return new Set(
        ALL_PERMISSIONS.filter((p) => !MANAGER_DENIED.includes(p)),
      );
    case "MEMBER":
      return new Set(ALL_PERMISSIONS.filter((p) => !MEMBER_DENIED.includes(p)));
    case "DATAROOM_MEMBER":
      return new Set(DATAROOM_MEMBER_PERMISSIONS);
    default:
      // Unknown / future roles are denied everything by default.
      return new Set<PermissionAction>();
  }
}

/**
 * True when `role` holds every required permission verb.
 */
export function hasAllPermissions(
  role: Role | string,
  required: PermissionAction[],
): boolean {
  if (required.length === 0) return true;
  const granted = getPermissionsByRole(role);
  return required.every((p) => granted.has(p));
}

/** True for the dataroom-scoped role, which needs per-room entitlement checks. */
export function isDataroomScopedRole(role: Role | string): boolean {
  return role === "DATAROOM_MEMBER";
}

import { createHash } from "crypto";

export const hashToken = (
  token: string,
  {
    noSecret = false,
  }: {
    noSecret?: boolean;
  } = {},
) => {
  return createHash("sha256")
    .update(`${token}${noSecret ? "" : process.env.NEXTAUTH_SECRET}`)
    .digest("hex");
};

import { NextApiRequest, NextApiResponse } from "next";

import { checkRateLimit, rateLimiters } from "@/ee/features/security";
import { isSamlEnforcedForEmailDomain } from "@/lib/api/teams/is-saml-enforced-for-email-domain";
import NextAuth, { type NextAuthOptions } from "next-auth";

import { identifyUser, trackAnalytics } from "@/lib/analytics";
import { authOptions } from "@/lib/auth/auth-options";
import { dub } from "@/lib/dub";
import { isBlacklistedEmail } from "@/lib/edge-config/blacklist";
import prisma from "@/lib/prisma";
import { log } from "@/lib/utils";
import { getIpAddress } from "@/lib/utils/ip";

export { authOptions } from "@/lib/auth/auth-options";

// This function can run for a maximum of 180 seconds
export const config = {
  maxDuration: 180,
};

const getAuthOptions = (req: NextApiRequest): NextAuthOptions => {
  // ─── Shared state for the current auth request ───
  // The signIn callback runs BEFORE the user is created in the DB (for new
  // OAuth users), so `user.id` there may not be a valid database ID.
  // We capture the SAML tenant in the callback (where we have the raw
  // OAuthProfile with `requested.tenant`) and use it in the signIn event
  // (where `user.id` is guaranteed to be the real database ID).
  let samlTenant: string | null = null;
  let samlUserEmail: string | null = null;

  return {
    ...authOptions,
    callbacks: {
      ...authOptions.callbacks,
      signIn: async ({ user, account, profile }) => {
        if (!user.email || (await isBlacklistedEmail(user.email))) {
          await identifyUser(user.email ?? user.id);
          await trackAnalytics({
            event: "User Sign In Attempted",
            email: user.email ?? undefined,
            userId: user.id,
          });
          return false;
        }

        // ─── SSO Enforcement ───
        // If user is NOT signing in via SAML, check if their domain requires SSO
        if (
          account?.provider !== "saml" &&
          account?.provider !== "saml-idp"
        ) {
          try {
            const ssoEnforced = await isSamlEnforcedForEmailDomain(user.email);
            if (ssoEnforced) {
              throw new Error("require-saml-sso");
            }
          } catch (error) {
            console.error("[Auth] SSO enforcement check failed:", error);
            throw error;
          }
        }

        // ─── SAML user → email domain validation ───
        if (
          account?.provider === "saml" ||
          account?.provider === "saml-idp"
        ) {
          // Get the SAML profile — comes from different places depending on provider
          let samlProfile: any;
          if (account.provider === "saml-idp") {
            // IdP-initiated: we attached the Jackson userInfo to user.profile
            samlProfile = (user as any).profile;
          } else {
            // SP-initiated OAuth: NextAuth passes the raw Jackson userInfo as `profile`
            samlProfile = profile;
          }

          const tenant = samlProfile?.requested?.tenant;
          if (tenant) {
            // ─── Email domain validation ───
            // Verify the SAML user's email domain matches the team's ssoEmailDomain.
            // This prevents a misconfigured IdP from injecting users from unexpected domains.
            const team = await prisma.team.findUnique({
              where: { id: tenant },
              select: { ssoEmailDomain: true, id: true },
            });

            if (team?.ssoEmailDomain) {
              const userEmailDomain = user.email
                .split("@")[1]
                ?.toLowerCase();
              if (
                userEmailDomain !==
                team.ssoEmailDomain.toLowerCase()
              ) {
                console.warn(
                  `[SAML] Rejected: user ${user.email} domain does not match team ssoEmailDomain ${team.ssoEmailDomain}`,
                );
                return false;
              }
            }

            // Store tenant for the signIn event to handle auto-join.
            // We can't reliably do the userTeam upsert here because for
            // new users (or first-time SSO users), user.id is not yet a
            // valid database ID — NextAuth creates the user AFTER this
            // callback returns true.
            samlTenant = tenant;
            samlUserEmail = user.email;
          }
        }

        // Apply rate limiting for signin attempts
        try {
          if (req) {
            const clientIP = getIpAddress(req.headers);
            const rateLimitResult = await checkRateLimit(
              rateLimiters.auth,
              clientIP,
            );

            if (!rateLimitResult.success) {
              log({
                message: `Rate limit exceeded for IP ${clientIP} during signin attempt`,
                type: "error",
              });
              return false;
            }
          }
        } catch (error) {}

        return true;
      },
    },
    events: {
      ...authOptions.events,
      signIn: async (message) => {
        await Promise.allSettled([
          identifyUser(message.user.email ?? message.user.id),
          trackAnalytics({
            event: "User Signed In",
            email: message.user.email,
          }),
        ]);

        // ─── SAML: Auto-join workspace + clean up invitations ───
        // This runs AFTER the user is created in the DB, so message.user.id
        // is guaranteed to be the real database user ID.
        if (samlTenant) {
          const tenant = samlTenant;
          const userEmail = samlUserEmail;

          try {
            await prisma.userTeam.upsert({
              where: {
                userId_teamId: {
                  userId: message.user.id,
                  teamId: tenant,
                },
              },
              update: {},
              create: {
                userId: message.user.id,
                teamId: tenant,
                role: "MEMBER",
              },
            });
          } catch (error) {
            console.error(
              `[SAML] Failed to upsert userTeam for user ${message.user.id} in team ${tenant}:`,
              error,
            );
          }

          // Clean up any pending invitations for this user
          if (userEmail) {
            await prisma.invitation
              .deleteMany({
                where: {
                  email: userEmail,
                  teamId: tenant,
                },
              })
              .catch(() => {
                // No invitation to clean up
              });
          }
        }

        if (message.isNewUser) {
          const { dub_id } = req.cookies;
          if (dub_id && process.env.DUB_API_KEY) {
            try {
              await dub.track.lead({
                clickId: dub_id,
                eventName: "Sign Up",
                customerExternalId: message.user.id,
                customerName: message.user.name,
                customerEmail: message.user.email,
                customerAvatar: message.user.image ?? undefined,
              });
            } catch (err) {
              console.error("dub.track.lead failed", err);
            }
          }
        }
      },
    },
  };
};

